LinkedIn Login, Sign in | LinkedIn (function cdnMonitor() {
  if (typeof window === "undefined" || typeof document === "undefined") {
    return;
  }
  const w = window;
  const d = document;
  const el = d.getElementById("cdn-monitor");
  if (!el) {
    return;
  }
  const generateRandomUUID = () => {
    if (typeof crypto !== "undefined" && crypto?.randomUUID) {
      return crypto?.randomUUID();
    }
    return "xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx".replace(/[xy]/g, (char) => {
      const random = Math.floor(Math.random() * 16);
      const value = char === "x" ? random : random % 4 + 8;
      return value.toString(16);
    });
  };
  const mainBundleCdnUrl = el.getAttribute("data-url") || "";
  const importMapBundleCdnUrl = el.getAttribute("data-url-importmap") || "";
  const csrfToken = el.getAttribute("data-csrf") || "";
  const trackInfo = el.getAttribute("data-track") || "";
  const isLoggedIn = el.getAttribute("data-is-logged-in");
  const url = mainBundleCdnUrl ? new URL(mainBundleCdnUrl, location.href).href : "";
  const urlImportMap = importMapBundleCdnUrl ? new URL(importMapBundleCdnUrl, location.href).href : "";
  let loadTriggered = false;
  let execTriggered = false;
  el.remove();
  function getTrackingMeta() {
    try {
      const raw = d.querySelector('meta[name="como-t"]')?.getAttribute("content");
      return raw ? JSON.parse(raw) : null;
    } catch {
      return null;
    }
  }
  function getResourceTiming(src) {
    try {
      if (typeof performance === "undefined" || !performance.getEntriesByName) {
        return {
          state: "unsupported"
        };
      }
      const entries = performance.getEntriesByName(src);
      const entry = entries[entries.length - 1];
      if (!entry) {
        return {
          state: "missing"
        };
      }
      return {
        state: "present",
        duration: Math.round(entry.duration),
        encodedBodySize: entry.encodedBodySize,
        requestStart: Math.round(entry.requestStart),
        responseEnd: Math.round(entry.responseEnd),
        responseStart: Math.round(entry.responseStart),
        responseStatus: typeof entry.responseStatus === "number" ? entry.responseStatus : "unknown",
        transferSize: entry.transferSize
      };
    } catch {
      return {
        state: "error"
      };
    }
  }
  function getDiagnosticFetchDiagnostics(src) {
    try {
      if (typeof fetch === "undefined") {
        return Promise.resolve({
          state: "unsupported"
        });
      }
      const controller = typeof AbortController !== "undefined" ? new AbortController() : null;
      let timeoutId;
      const timeout = new Promise((resolve) => {
        timeoutId = setTimeout(() => {
          controller?.abort();
          resolve({
            state: "timeout"
          });
        }, 3e3);
      });
      const diagnostics = fetch(src, {
        method: "GET",
        mode: "cors",
        credentials: "omit",
        signal: controller?.signal
      }).then(async (response) => {
        const body = await response.arrayBuffer().catch(() => new ArrayBuffer(0));
        clearTimeout(timeoutId);
        return {
          state: "present",
          responseStatus: response.status,
          responseType: response.type,
          bodyBytes: body.byteLength,
          xCdn: response.headers.get("x-cdn") || "missing",
          xCache: response.headers.get("x-cache") || "missing",
          xCdnClientIpVersion: response.headers.get("x-cdn-client-ip-version") || "missing",
          xCdnProto: response.headers.get("x-cdn-proto") || "missing",
          xCdnRcode: response.headers.get("x-cdn-rcode") || "missing"
        };
      }, () => {
        clearTimeout(timeoutId);
        return {
          state: "error"
        };
      });
      return Promise.race([
        diagnostics,
        timeout
      ]);
    } catch {
      return Promise.resolve({
        state: "error"
      });
    }
  }
  async function getLoadFailureDiagnostics(src) {
    const timing = getResourceTiming(src);
    const visibilityState = d.visibilityState || "unknown";
    const readyState = d.readyState || "unknown";
    const diagnosticFetch = typeof timing.responseStatus === "number" && timing.responseStatus >= 400 ? {
      state: "skipped"
    } : await getDiagnosticFetchDiagnostics(src);
    const details = [
      "visibilityState=" + visibilityState,
      "readyState=" + readyState,
      "webdriver=" + String(typeof navigator !== "undefined" && navigator?.webdriver === true),
      "resourceTiming=" + timing.state
    ];
    if (timing.state === "present") {
      details.push("duration=" + timing.duration, "requestStart=" + timing.requestStart, "responseStart=" + timing.responseStart, "responseEnd=" + timing.responseEnd, "transferSize=" + timing.transferSize, "encodedBodySize=" + timing.encodedBodySize, "responseStatus=" + timing.responseStatus);
    }
    details.push("diagnosticFetch=" + diagnosticFetch.state);
    if (diagnosticFetch.state === "present") {
      details.push("diagnosticFetchStatus=" + diagnosticFetch.responseStatus, "diagnosticFetchResponseType=" + diagnosticFetch.responseType, "diagnosticFetchBodyBytes=" + diagnosticFetch.bodyBytes, "x-cdn=" + diagnosticFetch.xCdn, "x-cache=" + diagnosticFetch.xCache, "x-cdn-client-ip-version=" + diagnosticFetch.xCdnClientIpVersion, "x-cdn-proto=" + diagnosticFetch.xCdnProto, "x-cdn-rcode=" + diagnosticFetch.xCdnRcode);
    }
    return details.join(" ");
  }
  function fireJetError(error, tags) {
